// @est/search-wasm: wasm implementation of the SearchIndex ABI.
// The artifact under pkg/ is generated by scripts/build-wasm.sh
// (wasm-pack --target web). The module imports nothing at load time: if
// the artifact is absent, initWasm() rejects and callers stay on the
// @est/search TS twin.

import type { SearchDoc, SearchHit, SearchIndex } from "@est/search";

export type { SearchDoc, SearchHit, SearchIndex };

type GlueIndex = {
  add(doc: string): void;
  build(): void;
  size(): number;
  search(query: string, limit: number): string;
};

type Glue = {
  default: (input?: ArrayBuffer | Promise<Response>) => Promise<void>;
  SearchIndex: new () => GlueIndex;
};

let glue: Promise<Glue> | null = null;

async function loadGlue(): Promise<Glue> {
  const mod = (await import("../pkg/search_wasm.js")) as unknown as Glue;
  try {
    const url = new URL("../pkg/search_wasm_bg.wasm", import.meta.url);
    const res = await fetch(url);
    await mod.default(await res.arrayBuffer());
  } catch {
    // Environments that resolve the wasm URL themselves.
    await mod.default();
  }
  return mod;
}

/** Initialize the wasm module once; safe to call repeatedly. */
export function initWasm(): Promise<Glue> {
  glue ??= loadGlue();
  return glue;
}

/**
 * Adapter presenting the wasm core as a true SearchIndex: the glue
 * exchanges JSON strings at the boundary; objects inside the adapter.
 */
class WasmSearchIndexAdapter implements SearchIndex {
  #inner: GlueIndex;

  constructor(inner: GlueIndex) {
    this.#inner = inner;
  }

  add(doc: SearchDoc): void {
    this.#inner.add(JSON.stringify(doc));
  }

  build(): void {
    this.#inner.build();
  }

  get size(): number {
    return this.#inner.size();
  }

  search(query: string, limit = 20): SearchHit[] {
    return JSON.parse(this.#inner.search(query, limit)) as SearchHit[];
  }
}

/** Create the wasm-backed index. Call initWasm() first (or use indexDocsWasm). */
export async function createWasmSearchIndex(): Promise<SearchIndex> {
  const { SearchIndex } = await initWasm();
  return new WasmSearchIndexAdapter(new SearchIndex());
}

/** Init + bulk load + build in one call. */
export async function indexDocsWasm(docs: readonly SearchDoc[]): Promise<SearchIndex> {
  const index = await createWasmSearchIndex();
  for (const d of docs) index.add(d);
  index.build();
  return index;
}
